import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '../../lib/utils';

const badgeVariants = cva(
  'inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2',
  {
    variants: {
      variant: {
        default: 'border-transparent bg-slate-900 text-white hover:bg-slate-800 focus:ring-slate-300 focus:ring-offset-white',
        secondary: 'border-transparent bg-slate-100 text-slate-900 hover:bg-slate-200 focus:ring-slate-300 focus:ring-offset-white',
        destructive: 'border-transparent bg-red-100 text-red-700 hover:bg-red-200 focus:ring-red-300 focus:ring-offset-white',
        outline: 'text-slate-900 border-slate-200 focus:ring-slate-300 focus:ring-offset-white'
      }
    },
    defaultVariants: {
      variant: 'default'
    }
  }
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

export function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}
